window.ATHENA_KB = [{"id": "p001", "cat": "3Dプリンター", "q": ["3Dプリンターとは何ですか", "3Dプリンターって何", "3Dプリンターの仕組みを教えて"], "a": "3Dプリンターは、3Dデータをもとに材料を少しずつ重ねて立体物を作る機械です。薄い層を何百枚も積み重ねることで、複雑な形でも型なしで作れます。", "src": "デモ用データ"}, {"id": "p002", "cat": "3Dプリンター", "q": ["FDMとは何ですか", "熱溶解積層法とは", "フィラメントを溶かして作る方式の名前は"], "a": "FDM（熱溶解積層法）は、糸状の樹脂（フィラメント）を熱で溶かし、ノズルから押し出しながら積み重ねる方式です。家庭用3Dプリンターで最も一般的な方式です。", "src": "デモ用データ"}, {"id": "p003", "cat": "3Dプリンター", "q": ["光造形とは何ですか", "SLA方式とは", "液体の樹脂を使う3Dプリンターの方式は"], "a": "光造形（SLA／DLP方式）は、液体のレジン（光硬化樹脂）に紫外線や光を当てて固めながら積み重ねる方式です。表面がなめらかで細かい造形が得意です。", "src": "デモ用データ"}, {"id": "p004", "cat": "3Dプリンター", "q": ["フィラメントとは何ですか", "3Dプリンターの材料の糸の名前は"], "a": "フィラメントは、FDM方式の3Dプリンターで使う糸状の材料です。直径1.75mmのものが一般的で、リールに巻かれて販売されています。", "src": "デモ用データ"}, {"id": "p005", "cat": "3Dプリンター", "q": ["PLAとは何ですか", "PLAフィラメントの特徴は"], "a": "PLAは植物由来の成分を含む樹脂で、3Dプリンターで最も扱いやすいフィラメントです。反りにくく初心者向きですが、熱に弱く、夏の車内などで変形することがあります。", "src": "デモ用データ"}, {"id": "p006", "cat": "3Dプリンター", "q": ["ABSとは何ですか", "ABSフィラメントの特徴は"], "a": "ABSは強度と耐熱性に優れた樹脂です。ただし造形中に反りやすく、冷えると収縮するため、造形室を温かく保てるプリンターが向いています。", "src": "デモ用データ"}, {"id": "p007", "cat": "3Dプリンター", "q": ["PETGとは何ですか", "PETGフィラメントの特徴は"], "a": "PETGは、PLAの扱いやすさとABSの丈夫さの中間くらいの性質を持つフィラメントです。層同士がくっつきやすく、水にも比較的強い材料です。", "src": "デモ用データ"}, {"id": "p008", "cat": "3Dプリンター", "q": ["ノズルとは何ですか", "3Dプリンターのノズルの役割は", "ノズルの温度はどれくらいですか"], "a": "ノズルはフィラメントを溶かして押し出す先端の部品です。PLAでは200℃前後まで熱します。先端の穴の大きさは0.4mmが標準的です。", "src": "デモ用データ"}, {"id": "p009", "cat": "3Dプリンター", "q": ["ヒートベッドとは何ですか", "ベッドを温める理由は"], "a": "ヒートベッドは造形物を載せる台を温める仕組みです。台を温めることで造形物がはがれにくくなり、反りも抑えられます。", "src": "デモ用データ"}, {"id": "p010", "cat": "3Dプリンター", "q": ["積層ピッチとは何ですか", "レイヤー高さとは", "層の厚さを変えるとどうなりますか"], "a": "積層ピッチ（レイヤー高さ）は、1層分の厚さのことです。薄くすると表面がきれいになりますが時間がかかります。0.2mm前後が標準的です。", "src": "デモ用データ"}, {"id": "p011", "cat": "3Dプリンター", "q": ["インフィルとは何ですか", "充填率とは", "中身の詰め具合を決める設定は"], "a": "インフィルは造形物の内部をどれくらい詰めるかを決める設定です。100%で中身が詰まった状態、20%程度でも日常の用途には十分な強度が出ることが多いです。", "src": "デモ用データ"}, {"id": "p012", "cat": "3Dプリンター", "q": ["サポート材とは何ですか", "宙に浮いた部分はどうやって作りますか"], "a": "サポート材は、宙に浮いた部分や急な傾斜を下から支えるための仮の構造です。造形が終わったら取り外します。形を工夫してサポートを減らすことも大切です。", "src": "デモ用データ"}, {"id": "p013", "cat": "3Dプリンター", "q": ["スライサーとは何ですか", "スライスソフトの役割は"], "a": "スライサーは、3Dデータをプリンターが動くための命令（層ごとの道筋）に変換するソフトです。温度や速度などの設定もここで行います。", "src": "デモ用データ"}, {"id": "p014", "cat": "3Dプリンター", "q": ["Gコードとは何ですか", "3Dプリンターへの命令の形式は"], "a": "Gコードは工作機械への命令を書く形式で、3Dプリンターでも使われます。「どこへ動いて、どれだけ材料を出すか」といった指示が1行ずつ書かれています。", "src": "デモ用データ"}, {"id": "p015", "cat": "3Dプリンター", "q": ["ブリムとは何ですか", "ラフトとは何ですか", "造形物の周りの縁は何ですか"], "a": "ブリムは造形物の周りに広げる薄い縁で、台へのくっつきを良くします。ラフトは造形物の下に敷く土台です。どちらも完成後に取り除きます。", "src": "デモ用データ"}, {"id": "p016", "cat": "3Dプリンター", "q": ["糸引きの原因は何ですか", "ストリンギングとは", "造形物に糸くずのようなものが付きます"], "a": "糸引き（ストリンギング）は、ノズルが移動するときに溶けた樹脂が糸を引く現象です。ノズル温度を少し下げる、引き戻し（リトラクション）の設定を調整すると改善します。", "src": "デモ用データ"}, {"id": "p017", "cat": "3Dプリンター", "q": ["造形物が反る原因は何ですか", "ワーピングとは", "角が浮き上がってしまいます"], "a": "反り（ワーピング）は、樹脂が冷えるときに収縮して角が浮き上がる現象です。ベッドを温める、ブリムを付ける、風を当てないようにすると抑えられます。", "src": "デモ用データ"}, {"id": "p018", "cat": "3Dプリンター", "q": ["3Dプリントにはどれくらい時間がかかりますか", "造形時間の目安は"], "a": "造形時間は大きさと設定で大きく変わります。手のひらサイズのもので数十分から数時間、大きなものや細かい設定では一晩かかることもあります。", "src": "デモ用データ"}, {"id": "p019", "cat": "3Dプリンター", "q": ["ノズルが詰まる原因は何ですか", "フィラメントが出てこなくなりました"], "a": "ノズル詰まりの原因は、焦げた材料の蓄積、フィラメントに付いたほこり、温度の不適合などです。詰まったら無理に押し込まず、加熱して取り除くか、ノズルを交換します。", "src": "デモ用データ"}, {"id": "p020", "cat": "3Dプリンター", "q": ["第一層が大事な理由は何ですか", "ファーストレイヤーとは"], "a": "第一層は造形物全体の土台です。ここがうまく台にくっつかないと、途中で倒れたり位置がずれたりして失敗します。印刷の最初の数分は様子を見るのがおすすめです。", "src": "デモ用データ"}, {"id": "p021", "cat": "3Dプリンター", "q": ["3Dプリンターで何が作れますか", "3Dプリンターの活用例を教えて"], "a": "スマホスタンドや小物入れなどの日用品、試作品（プロトタイプ）、模型のパーツ、治具（作業を助ける道具）など、さまざまなものが作れます。", "src": "デモ用データ"}, {"id": "p022", "cat": "3Dプリンター", "q": ["積層痕とは何ですか", "3Dプリントの表面の縞模様は何ですか"], "a": "積層痕は、層を重ねた跡が表面に縞模様として残るものです。積層ピッチを薄くすると目立ちにくくなり、やすりがけや塗装で消すこともできます。", "src": "デモ用データ"}, {"id": "p023", "cat": "3Dプリンター", "q": ["ベッドレベリングとは何ですか", "台の水平出しはなぜ必要ですか"], "a": "ベッドレベリングは、ノズルと台の間隔を全体で均一にそろえる調整です。間隔がばらつくと、第一層が付く場所と付かない場所ができて失敗の原因になります。", "src": "デモ用データ"}, {"id": "p024", "cat": "3Dプリンター", "q": ["フィラメントの保管方法を教えて", "フィラメントは湿気に弱いですか", "フィラメントが湿気を吸ったらどうしますか", "フィラメントが湿気たときの対処法は", "フィラメントが湿気たみたいです", "フィラメントが湿気てしまった時の対処法は"], "a": "フィラメントは湿気を吸うと造形の質が落ちます。乾燥剤と一緒に密閉袋や密閉容器で保管するのが基本です。湿気を吸った場合は乾燥させると回復することがあります。", "src": "デモ用データ"}, {"id": "p025", "cat": "レーザーカッター", "q": ["レーザーカッターとは何ですか", "レーザー加工機の仕組みを教えて"], "a": "レーザーカッターは、細く絞ったレーザー光の熱で材料を焼き切ったり、表面を削って模様を付けたりする機械です。データ通りの正確な形に加工できます。", "src": "デモ用データ"}, {"id": "p026", "cat": "レーザーカッター", "q": ["CO2レーザーとダイオードレーザーの違いは何ですか", "レーザーの種類を教えて"], "a": "CO2レーザーは出力が高く、木やアクリルの切断が得意な大型機に多く使われます。ダイオードレーザーは小型で安価な機種に多く、彫刻や薄い材料の加工に向いています。", "src": "デモ用データ"}, {"id": "p027", "cat": "レーザーカッター", "q": ["切断と彫刻の違いは何ですか", "レーザー彫刻とは何ですか"], "a": "切断は材料を貫通させて切り抜く加工、彫刻は表面だけを削って文字や模様を付ける加工です。出力とスピードの設定を変えて使い分けます。", "src": "デモ用データ"}, {"id": "p028", "cat": "レーザーカッター", "q": ["レーザーカッターで切れない素材は何ですか", "塩ビはレーザーで切れますか"], "a": "塩化ビニル（塩ビ）は、加熱すると有害なガスが出るため絶対に加工してはいけません。金属の切断も一般的な加工機ではできません。素材が不明なものは加工しないのが原則です。", "src": "デモ用データ"}, {"id": "p029", "cat": "レーザーカッター", "q": ["カーフとは何ですか", "レーザーで切ると寸法が小さくなるのはなぜですか"], "a": "カーフはレーザーで焼き切られた切り幅のことです。切り幅の分だけ材料がなくなるので、はめ合わせの部品では切り幅を考えて寸法を調整します。", "src": "デモ用データ"}, {"id": "p030", "cat": "レーザーカッター", "q": ["レーザーの焦点の合わせ方を教えて", "フォーカス調整とは何ですか"], "a": "焦点（フォーカス）は、レーザー光が最も細く絞られる位置を材料の表面に合わせることです。焦点がずれると切れが悪くなったり、切り口が太くなったりします。", "src": "デモ用データ"}, {"id": "p031", "cat": "レーザーカッター", "q": ["レーザーの出力とスピードの関係を教えて", "切れないときはどう調整しますか"], "a": "出力を上げるかスピードを下げると、より深く加工できます。ただし強すぎると焦げが広がります。端材で試し切りをして、材料ごとにちょうどよい設定を探すのが基本です。", "src": "デモ用データ"}, {"id": "p032", "cat": "レーザーカッター", "q": ["ベクターデータとラスターデータの違いは何ですか", "レーザー加工のデータ形式を教えて"], "a": "ベクターデータは線の情報でできていて切断や線彫刻に使い、ラスターデータは点の集まりの画像で面の彫刻に使います。切断したい輪郭はベクターで用意します。", "src": "デモ用データ"}, {"id": "p033", "cat": "レーザーカッター", "q": ["アクリルはレーザーで加工できますか", "アクリル加工の特徴を教えて"], "a": "アクリルはレーザー加工と相性のよい素材で、切り口が透明でなめらかに仕上がります。保護紙を付けたまま加工すると、煙による汚れを防げます。", "src": "デモ用データ"}, {"id": "p034", "cat": "レーザーカッター", "q": ["MDFとは何ですか", "木材をレーザーで切るときの注意は"], "a": "MDFは木の繊維を固めた板で、均一で加工しやすい素材です。木材は厚みや部分によって切れ具合が変わることがあり、焦げ跡が付きやすいので設定の調整が必要です。", "src": "デモ用データ"}, {"id": "p035", "cat": "レーザーカッター", "q": ["レーザー加工で換気が必要な理由は何ですか", "加工の煙はどうしますか"], "a": "レーザー加工では材料が焼けるため煙とにおいが出ます。健康と安全のため、排煙装置や換気で煙を外に出しながら使います。加工中は機械から目を離さないことも大切です。", "src": "デモ用データ"}, {"id": "p036", "cat": "レーザーカッター", "q": ["レーザーは目に危険ですか", "レーザー加工機の安全対策を教えて"], "a": "レーザー光は目に入ると大変危険です。加工機のカバーは安全装置を兼ねているので、開けたまま動かしたり、安全装置を無効化したりしてはいけません。", "src": "デモ用データ"}, {"id": "p037", "cat": "レーザーカッター", "q": ["はめ合いの寸法はどう決めますか", "部品同士をはめるときのクリアランスは"], "a": "部品同士をはめ合わせる設計では、切り幅（カーフ）の分と、きつすぎず緩すぎないためのすき間（クリアランス）を考えます。小さい試作品で実際に確かめるのが確実です。", "src": "デモ用データ"}, {"id": "p038", "cat": "レーザーカッター", "q": ["レーザー加工の焦げ跡を減らす方法は", "切り口が焦げてしまいます"], "a": "焦げ跡は、出力を必要最小限にすること、表面にマスキングテープを貼ること、エアアシストで炎と煙を吹き飛ばすことで減らせます。", "src": "デモ用データ"}, {"id": "p039", "cat": "はんだ・電子工作", "q": ["はんだ付けとは何ですか", "はんだ付けの基本を教えて"], "a": "はんだ付けは、金属の合金（はんだ）を熱で溶かして、部品と基板を電気的・機械的につなぐ作業です。部品と基板の両方を温めてからはんだを流すのがコツです。", "src": "デモ用データ"}, {"id": "p040", "cat": "はんだ・電子工作", "q": ["はんだごての温度はどれくらいですか", "はんだごての使い方を教えて"], "a": "はんだ付けでは、こて先を300〜350℃くらいに設定するのが一般的です。熱しすぎると部品を傷め、足りないとうまく流れません。使わないときはこて台に戻し、やけどに注意します。", "src": "デモ用データ"}, {"id": "p041", "cat": "はんだ・電子工作", "q": ["フラックスとは何ですか", "フラックスの役割を教えて"], "a": "フラックスは、金属の表面の酸化膜を取り除いて、はんだの流れをよくする薬剤です。糸はんだの中にはフラックスが入っていて、溶けると表面をきれいにします。", "src": "デモ用データ"}, {"id": "p042", "cat": "はんだ・電子工作", "q": ["鉛フリーはんだとは何ですか", "鉛入りはんだとの違いは"], "a": "鉛フリーはんだは、環境や健康への配慮から鉛を使わないはんだです。従来の鉛入りはんだより少し高い温度で溶けるため、こての温度設定を高めにします。", "src": "デモ用データ"}, {"id": "p043", "cat": "はんだ・電子工作", "q": ["イモはんだとは何ですか", "はんだ付けの失敗例を教えて", "はんだ付けがうまくいかない時は", "はんだ付けで失敗した時の直し方を教えて"], "a": "イモはんだは、はんだが丸く固まって部品と基板にしっかり付いていない不良の状態です。温め不足が原因で、見た目は付いていても電気が流れないことがあります。", "src": "デモ用データ"}, {"id": "p044", "cat": "はんだ・電子工作", "q": ["ブリッジとは何ですか", "隣のピン同士がくっついてしまいました"], "a": "ブリッジは、隣り合う端子同士がはんだでつながってしまう不良です。はんだの量を減らすことと、はんだ吸い取り線で余分なはんだを取り除くことで直せます。", "src": "デモ用データ"}, {"id": "p045", "cat": "はんだ・電子工作", "q": ["LEDとは何ですか", "LEDに極性はありますか"], "a": "LEDは電気を流すと光る部品（発光ダイオード）です。プラスとマイナスの向き（極性）があり、足の長い方がプラス（アノード）です。逆向きでは光りません。", "src": "デモ用データ"}, {"id": "p046", "cat": "はんだ・電子工作", "q": ["抵抗とは何ですか", "抵抗のカラーコードの読み方は"], "a": "抵抗は電流の流れを調整する部品です。本体の色の帯（カラーコード）で抵抗値が分かります。LEDと組み合わせて、LEDに流れる電流をちょうどよくするために使います。", "src": "デモ用データ"}, {"id": "p047", "cat": "はんだ・電子工作", "q": ["オームの法則とは何ですか", "電圧と電流と抵抗の関係を教えて"], "a": "オームの法則は、電圧＝電流×抵抗という関係です。例えば5Vの電圧で10Ωの抵抗をつなぐと、0.5Aの電流が流れます。電子工作の計算の基本です。", "src": "デモ用データ"}, {"id": "p048", "cat": "はんだ・電子工作", "q": ["直列と並列の違いは何ですか", "電池の直列と並列を教えて"], "a": "直列は部品を数珠つなぎにする接続で、電池を直列にすると電圧が合計されます。並列は横に並べる接続で、電池を並列にすると電圧は同じで長持ちします。", "src": "デモ用データ"}, {"id": "p049", "cat": "はんだ・電子工作", "q": ["ブレッドボードとは何ですか", "はんだ付けなしで回路を組む道具は"], "a": "ブレッドボードは、穴に部品や線を差し込むだけで回路を組める実験用の板です。はんだ付けが不要なので、試作や実験を手早く行えます。", "src": "デモ用データ"}, {"id": "p050", "cat": "はんだ・電子工作", "q": ["Arduinoとは何ですか", "アルドゥイーノって何ですか"], "a": "Arduinoは、プログラムで電子部品を制御できるマイコンボードとその開発環境の名前です。センサーやモーターと組み合わせて、さまざまな仕掛けを作れます。", "src": "デモ用データ"}, {"id": "p051", "cat": "はんだ・電子工作", "q": ["マイコンとは何ですか", "マイクロコントローラとは"], "a": "マイコン（マイクロコントローラ）は、プログラム通りに信号の入出力を行う小さなコンピュータのチップです。家電や工作の自動制御に広く使われています。", "src": "デモ用データ"}, {"id": "p052", "cat": "はんだ・電子工作", "q": ["センサーとは何ですか", "電子工作で使うセンサーの例を教えて"], "a": "センサーは、光・温度・距離・動きなどの情報を電気信号に変える部品です。明るさを測る光センサー、温度を測る温度センサー、物との距離を測る超音波センサーなどがあります。", "src": "デモ用データ"}, {"id": "p053", "cat": "はんだ・電子工作", "q": ["サーボモーターとは何ですか", "サーボとDCモーターの違いは"], "a": "サーボモーターは、指定した角度まで回って止まるモーターです。DCモーターは回り続けるモーターで、サーボは角度を決められる点が違います。ロボットの関節などに使われます。", "src": "デモ用データ"}, {"id": "p054", "cat": "はんだ・電子工作", "q": ["ステッピングモーターとは何ですか", "ステップモーターの特徴は"], "a": "ステッピングモーターは、電気信号の数だけ少しずつ回るモーターで、回転量を正確に決められます。3Dプリンターやレーザー加工機の位置決めに使われています。", "src": "デモ用データ"}, {"id": "p055", "cat": "はんだ・電子工作", "q": ["ショートとは何ですか", "短絡するとどうなりますか"], "a": "ショート（短絡）は、プラスとマイナスが抵抗なしに直接つながることです。大電流が流れて発熱や発火の原因になるため、回路を組んだら電源を入れる前に配線を確認します。", "src": "デモ用データ"}, {"id": "p056", "cat": "はんだ・電子工作", "q": ["テスターの使い方を教えて", "マルチメーターで何が測れますか"], "a": "テスター（マルチメーター）は、電圧・電流・抵抗などを測る道具です。つながっているかを確認する導通チェックもでき、回路の不具合探しに欠かせません。", "src": "デモ用データ"}, {"id": "p057", "cat": "はんだ・電子工作", "q": ["コンデンサとは何ですか", "コンデンサの役割を教えて"], "a": "コンデンサは、電気を一時的にためたり放したりする部品です。電源の波をなめらかにしたり、タイミングを作る回路に使われます。向きのある種類もあります。", "src": "デモ用データ"}, {"id": "p058", "cat": "はんだ・電子工作", "q": ["ダイオードとは何ですか", "ダイオードの働きを教えて"], "a": "ダイオードは、電気を一方向にだけ流す部品です。逆向きの電圧から回路を守ったり、交流を直流に変える働きに使われます。LEDもダイオードの一種です。", "src": "デモ用データ"}, {"id": "p059", "cat": "はんだ・電子工作", "q": ["基板とは何ですか", "PCBとは何ですか"], "a": "基板（PCB）は、電子部品を取り付けて配線するための板です。緑色の板に銅の配線パターンが作られていて、部品をはんだ付けして回路を完成させます。", "src": "デモ用データ"}, {"id": "p060", "cat": "はんだ・電子工作", "q": ["単三電池の電圧は何ボルトですか", "乾電池の種類と電圧を教えて"], "a": "単三形の乾電池は1本で1.5Vです。充電式のニッケル水素電池は1.2Vです。機器の指定に合わせて本数と種類を選びます。", "src": "デモ用データ"}, {"id": "p061", "cat": "はんだ・電子工作", "q": ["スイッチの仕組みを教えて", "タクトスイッチとは何ですか"], "a": "スイッチは電気の通り道を開いたり閉じたりする部品です。タクトスイッチは押している間だけつながる小型のスイッチで、ボタンの入力によく使われます。", "src": "デモ用データ"}, {"id": "p062", "cat": "はんだ・電子工作", "q": ["ジャンパーワイヤとは何ですか", "ブレッドボードで使う線の名前は"], "a": "ジャンパーワイヤは、ブレッドボードや基板の穴同士をつなぐための線です。両端がピンになったものや、差し込みやすい形のものがあります。", "src": "デモ用データ"}, {"id": "p063", "cat": "コマの物理", "q": ["コマが倒れずに回り続けるのはなぜですか", "コマが回る仕組みを教えて"], "a": "コマが倒れないのは、回転によって生まれる角運動量が、倒れようとする力を打ち消すからです。回転が速いほど姿勢を保つ力が強く、遅くなると揺れが大きくなって倒れます。", "src": "デモ用データ"}, {"id": "p064", "cat": "コマの物理", "q": ["ジャイロ効果とは何ですか", "ジャイロスコープの原理を教えて"], "a": "ジャイロ効果は、回転している物体がその回転の向きを保とうとする性質です。コマや自転車の車輪、姿勢制御の装置などに応用されています。", "src": "デモ用データ"}, {"id": "p065", "cat": "コマの物理", "q": ["コマの重心は低い方がいいですか", "重心とコマの安定性の関係は"], "a": "一般に、重心が低いコマは倒れにくく安定します。ただし、ひっくり返るタイプのコマなど、形によっては重心の位置が仕掛けの鍵になるものもあります。", "src": "デモ用データ"}, {"id": "p066", "cat": "コマの物理", "q": ["慣性モーメントとは何ですか", "慣性モーメントを分かりやすく教えて"], "a": "慣性モーメントは、回転のしにくさ・止まりにくさを表す量です。重さが回転の中心から遠いところに集まるほど大きくなり、一度回すと長く回り続けます。", "src": "デモ用データ"}, {"id": "p067", "cat": "コマの物理", "q": ["ひっくり返りゴマの仕組みを教えて", "逆立ちゴマはなぜひっくり返るのですか"], "a": "ひっくり返りゴマ（逆立ちゴマ）は、球面状の体と短い軸を持つコマです。回すと摩擦と回転の相互作用で重心の位置関係が変わり、軸を下にして逆立ちした状態で回り続けます。", "src": "デモ用データ"}, {"id": "p068", "cat": "コマの物理", "q": ["歳差運動とは何ですか", "コマの首振り運動の名前は"], "a": "歳差運動は、回転が弱まってきたコマの軸が、円を描くようにゆっくり首を振る運動です。地球の地軸にも同じ運動があり、春分点が少しずつ移動する現象として知られています。", "src": "デモ用データ"}, {"id": "p069", "cat": "コマの物理", "q": ["コマの軸がぶれる原因は何ですか", "コマが暴れるのはなぜですか"], "a": "軸のぶれは、重心が回転軸からずれていることや、形の左右非対称、軸先の傷などが原因です。重さの配分が均等なコマほど、ぶれずになめらかに回ります。", "src": "デモ用データ"}, {"id": "p070", "cat": "コマの物理", "q": ["コマが止まる理由は何ですか", "回転時間を決めるものは何ですか"], "a": "コマは、軸先と地面の摩擦や空気抵抗によって少しずつ回転のエネルギーを失って止まります。軸先の形状や、回す面の状態が回転時間に影響します。", "src": "デモ用データ"}, {"id": "p071", "cat": "コマの物理", "q": ["コマの縁を重くするとどうなりますか", "リムが重いコマの特徴は"], "a": "縁（リム）を重くすると慣性モーメントが大きくなり、回転が安定して長続きしやすくなります。フライホイールやはずみ車も同じ考え方の応用です。", "src": "デモ用データ"}, {"id": "p072", "cat": "コマの物理", "q": ["コマの材質で性能は変わりますか", "金属と木のコマの違いは"], "a": "材質で重さや摩擦、丈夫さが変わります。金属は重くて長く回るものが作りやすく、木は軽くて加工しやすい特徴があります。プラスチックは形の自由度が高い材質です。", "src": "デモ用データ"}, {"id": "p073", "cat": "コマの物理", "q": ["回転数が速いほどコマは安定しますか", "速く回すと倒れにくい理由は"], "a": "はい。一般に回転が速いほど角運動量が大きく、姿勢を保つ力が強くなります。ただし速すぎると空気抵抗や振動の影響も出てきます。", "src": "デモ用データ"}, {"id": "p074", "cat": "コマの物理", "q": ["空気抵抗はコマに影響しますか", "コマの形と空気抵抗の関係は"], "a": "空気抵抗は回転を少しずつ弱めます。表面の凹凸や大きな羽のような形は抵抗を増やします。なめらかな形ほどエネルギーの損失が少なくなります。", "src": "デモ用データ"}, {"id": "p075", "cat": "コマの物理", "q": ["コマの直径と回転の関係を教えて", "大きいコマと小さいコマの違いは"], "a": "直径が大きいコマは、同じ重さでも慣性モーメントが大きくなり、安定しやすい傾向があります。小さいコマは軽くて回しやすい反面、回転が弱まりやすい傾向があります。", "src": "デモ用データ"}, {"id": "p076", "cat": "コマの物理", "q": ["ベーゴマとは何ですか", "ベーゴマの遊び方を教えて"], "a": "ベーゴマは鋳物の小さなコマで、ひもを巻いて投げるように回します。台の上で相手のコマとぶつけ合って、弾き飛ばしたり先に止まったりしたら負け、という対戦遊びで親しまれてきました。", "src": "デモ用データ"}, {"id": "p077", "cat": "コマの物理", "q": ["コマの歴史を教えて", "独楽はいつからありますか"], "a": "コマは世界各地で古くから遊ばれてきた玩具で、土や木で作られたコマが各地の遺跡から見つかっています。日本でも古くから親しまれ、地域ごとにさまざまな形と遊び方が伝わっています。", "src": "デモ用データ"}, {"id": "p078", "cat": "コマの物理", "q": ["遠心力とは何ですか", "回転すると外向きの力が働く理由は"], "a": "遠心力は、回転しているものと一緒に回る視点から見たときに、外向きに働くように見える力です。回転が速いほど、また中心から遠いほど強く感じられます。", "src": "デモ用データ"}, {"id": "p079", "cat": "コマの物理", "q": ["角運動量保存則とは何ですか", "角運動量とは何ですか"], "a": "角運動量は回転の勢いを表す量で、外から回す力が加わらなければ一定に保たれます（角運動量保存則）。フィギュアスケートの選手が腕を縮めると回転が速くなるのはこのためです。", "src": "デモ用データ"}, {"id": "p080", "cat": "コマの物理", "q": ["コマの軸の太さはどう影響しますか", "ひもで回すコマの軸の工夫は"], "a": "ひもを巻いて回すコマでは、軸が太いと1回転で進むひもの量が増え、回転の伝わり方が変わります。手でひねるコマでは、軸の太さが握りやすさや回しやすさに影響します。", "src": "デモ用データ"}, {"id": "p081", "cat": "コマの物理", "q": ["コマの軸先の形にはどんな種類がありますか", "接地点の形で回り方は変わりますか"], "a": "軸先には、丸い形、とがった形、平らな形などがあります。丸い軸先はなめらかに回りやすく、とがった軸先は摩擦が小さい反面、面を傷つけやすいなど、それぞれ特徴があります。", "src": "デモ用データ"}, {"id": "p082", "cat": "コマの物理", "q": ["コマを長く回すコツはありますか", "コマの回転時間を伸ばす方法は"], "a": "一般的なコツは、まっすぐ安定して回し始めること、なめらかで平らな面で回すこと、軸先を清潔に保つことです。コマ自体の重さの配分や形も大きく影響します。", "src": "デモ用データ"}, {"id": "p083", "cat": "工作・科学一般", "q": ["接着剤の種類と使い分けを教えて", "瞬間接着剤と木工用ボンドの違いは"], "a": "瞬間接着剤は速く付く反面もろさがあり、木工用ボンドは木や紙に強く乾くまで時間がかかります。エポキシ系は強度が高く、金属やプラスチックにも使えます。材料に合った接着剤選びが大切です。", "src": "デモ用データ"}, {"id": "p084", "cat": "工作・科学一般", "q": ["紙やすりの番手とは何ですか", "やすりの目の粗さの数字の意味は"], "a": "紙やすりの番手は目の粗さを表す数字で、小さいほど粗く、大きいほど細かくなります。粗い番手で形を整え、細かい番手で仕上げるのが基本の順番です。", "src": "デモ用データ"}, {"id": "p085", "cat": "工作・科学一般", "q": ["ノギスの使い方を教えて", "ノギスで何が測れますか"], "a": "ノギスは、物の外側・内側の寸法と深さを0.1mm単位で測れる道具です。くちばしのような部分で物をはさんで目盛りを読みます。工作の寸法確認に欠かせません。", "src": "デモ用データ"}, {"id": "p086", "cat": "工作・科学一般", "q": ["ねじの種類を教えて", "木ねじとタッピングねじの違いは"], "a": "ねじには、木材に直接ねじ込む木ねじ、下穴にねじ山を作りながら入るタッピングねじ、ナットと組み合わせる小ねじなどがあります。相手の材料に合わせて選びます。", "src": "デモ用データ"}, {"id": "p087", "cat": "工作・科学一般", "q": ["ドライバーの種類を教えて", "六角ドライバーは何に使いますか"], "a": "ドライバーには、プラス・マイナス・六角などの先端形状があります。ねじの頭の形に合ったものを使わないと、ねじ頭をつぶしてしまいます。サイズを合わせることも大切です。", "src": "デモ用データ"}, {"id": "p088", "cat": "工作・科学一般", "q": ["カッターを安全に使う方法は", "刃物の安全な使い方を教えて"], "a": "カッターは、刃の進む先に手や体を置かないこと、切り終わったら刃をしまうこと、切るときはカッターマットを敷くことが基本です。刃が欠けたら新しい刃に替えます。", "src": "デモ用データ"}, {"id": "p089", "cat": "工作・科学一般", "q": ["塗装の基本を教えて", "塗料を塗る前の下準備は何ですか"], "a": "塗装は、表面の汚れや油分を落とし、必要なら下地（サーフェイサー）を塗ってから本塗りします。薄く何度か重ね塗りすると、垂れにくくきれいに仕上がります。", "src": "デモ用データ"}, {"id": "p090", "cat": "工作・科学一般", "q": ["熱可塑性樹脂と熱硬化性樹脂の違いは何ですか", "プラスチックの種類を教えて"], "a": "熱可塑性樹脂は熱で柔らかくなり、冷えると固まる性質を繰り返せるプラスチックです。熱硬化性樹脂は一度固まると熱で柔らかくなりません。PLAなどの工作用樹脂は熱可塑性です。", "src": "デモ用データ"}, {"id": "p091", "cat": "工作・科学一般", "q": ["バルサ材とは何ですか", "合板と無垢材の違いは"], "a": "バルサはとても軽くて柔らかい木材で、模型工作によく使われます。合板は薄い板を重ねて貼った材料で反りにくく、無垢材は一枚の木から切り出した材料です。", "src": "デモ用データ"}, {"id": "p092", "cat": "工作・科学一般", "q": ["アルミとステンレスの違いは何ですか", "真鍮とはどんな金属ですか"], "a": "アルミは軽くて加工しやすく、ステンレスは硬くて錆びにくい金属です。真鍮は銅と亜鉛の合金で、金色に近い色と加工のしやすさが特徴です。", "src": "デモ用データ"}, {"id": "p093", "cat": "工作・科学一般", "q": ["てこの原理とは何ですか", "てこを使うと楽になる理由は"], "a": "てこは、支点からの距離を変えることで、小さな力で大きなものを動かせる仕組みです。支点に近いところを押すより、遠いところを押す方が軽い力で済みます。", "src": "デモ用データ"}, {"id": "p094", "cat": "工作・科学一般", "q": ["滑車の仕組みを教えて", "動滑車を使うとどうなりますか"], "a": "滑車は、ひもの向きを変えたり、重いものを軽い力で持ち上げたりする仕組みです。動滑車を使うと、必要な力は半分になりますが、引くひもの長さは2倍になります。", "src": "デモ用データ"}, {"id": "p095", "cat": "工作・科学一般", "q": ["歯車のギア比とは何ですか", "ギアを組み合わせるとどうなりますか"], "a": "ギア比は、2つの歯車の歯数の比率です。小さい歯車から大きい歯車へ伝えると回転は遅くなり力が強くなり、逆にすると速く回りますが力は弱くなります。", "src": "デモ用データ"}, {"id": "p096", "cat": "工作・科学一般", "q": ["リンク機構とは何ですか", "リンク機構の例を教えて"], "a": "リンク機構は、棒と関節を組み合わせて動きを伝える仕組みです。回転を往復運動に変えたり、複雑な軌跡を描かせたりできます。ワイパーや踏みミシンなどに使われています。", "src": "デモ用データ"}, {"id": "p097", "cat": "工作・科学一般", "q": ["静電気とは何ですか", "冬に静電気が起きやすい理由は"], "a": "静電気は、物同士の摩擦などで電気が偏ってたまった状態です。乾燥した冬は電気が逃げにくいため、たまった電気が一気に流れてパチッとなりやすくなります。", "src": "デモ用データ"}, {"id": "p098", "cat": "工作・科学一般", "q": ["磁石の性質を教えて", "N極とS極の関係は"], "a": "磁石にはN極とS極があり、同じ極同士は退け合い、違う極同士は引き合います。鉄などの金属を引きつける力があり、方位磁針は地球の磁場を利用しています。", "src": "デモ用データ"}, {"id": "p099", "cat": "工作・科学一般", "q": ["電磁石とは何ですか", "電磁石の強さを変える方法は"], "a": "電磁石は、コイルに電流を流すと磁石になる仕組みです。電流を大きくしたり、コイルの巻き数を増やしたりすると強くなり、電流を切ると磁力が消えます。", "src": "デモ用データ"}, {"id": "p100", "cat": "工作・科学一般", "q": ["浮力とは何ですか", "物が水に浮く理由は"], "a": "浮力は、水中の物が押しのけた水の重さの分だけ、上向きに押し上げられる力です。物の平均の重さが水より軽いと浮き、重いと沈みます。船が浮くのもこの力のおかげです。", "src": "デモ用データ"}, {"id": "p101", "cat": "工作・科学一般", "q": ["振り子の周期は何で決まりますか", "振り子の速さを変えるには"], "a": "振り子の周期は、主にひもの長さで決まります。長いほどゆっくり、短いほど速く揺れます。おもりの重さや揺らす幅（小さい範囲では）にはほとんど影響されません。", "src": "デモ用データ"}, {"id": "p102", "cat": "工作・科学一般", "q": ["共鳴とは何ですか", "音の振動について教えて"], "a": "共鳴は、物の固有の振動数に合った振動が加わると、振れ幅が大きくなる現象です。楽器の胴が音を大きく響かせるのは共鳴の働きです。", "src": "デモ用データ"}, {"id": "p103", "cat": "工作・科学一般", "q": ["光の屈折とは何ですか", "水の中の物がずれて見える理由は"], "a": "屈折は、光が水やガラスなど違う物質の境目を通るときに進む向きが変わる現象です。水の中のストローが折れて見えるのは、屈折のためです。レンズもこの性質を使っています。", "src": "デモ用データ"}, {"id": "p104", "cat": "工作・科学一般", "q": ["表面張力とは何ですか", "水が盛り上がる理由は"], "a": "表面張力は、液体の表面が縮もうとする力です。コップの縁より水が少し盛り上がったり、水滴が丸くなったりするのはこの力のためです。アメンボが水面に浮かぶのも表面張力を利用しています。", "src": "デモ用データ"}, {"id": "p105", "cat": "メイカー一般", "q": ["Maker Faireとは何ですか", "メイカーフェアについて教えて"], "a": "Maker Faireは、手作りのものや技術作品を持ち寄って見せ合うイベントです。電子工作、ロボット、工芸、科学実験など、作ることが好きな人たちが集まって交流します。", "src": "デモ用データ"}, {"id": "p106", "cat": "メイカー一般", "q": ["メイカーとは何ですか", "Makerとはどういう意味ですか"], "a": "メイカー（Maker）は、既製品を買うだけでなく、自分で考えて手を動かしてものを作る人たちのことです。趣味の工作から技術開発まで、幅広い作り手を指します。", "src": "デモ用データ"}, {"id": "p107", "cat": "メイカー一般", "q": ["DIYとは何ですか", "DIYの意味を教えて"], "a": "DIYは「Do It Yourself」の略で、専門の業者に頼まず自分で作ったり直したりすることです。家具作りや部屋の改装、工作全般を指します。", "src": "デモ用データ"}, {"id": "p108", "cat": "メイカー一般", "q": ["ファブラボとは何ですか", "FabLabについて教えて"], "a": "ファブラボは、3Dプリンターやレーザーカッターなどのデジタル工作機械を備え、地域の人がものづくりを学び合える工房のネットワークです。世界各地にあります。", "src": "デモ用データ"}, {"id": "p109", "cat": "メイカー一般", "q": ["オープンソースハードウェアとは何ですか", "設計図を公開する考え方を教えて"], "a": "オープンソースハードウェアは、製品の設計図や回路図を公開し、誰でも作ったり改良したりできるようにする考え方です。知恵を共有して発展させる文化が背景にあります。", "src": "デモ用データ"}, {"id": "p110", "cat": "メイカー一般", "q": ["STL形式とは何ですか", "3Dプリントで使うファイル形式は"], "a": "STLは、3Dの形を小さな三角形の集まりで表すファイル形式です。3Dプリンターで印刷するデータの標準的な形式として広く使われています。", "src": "デモ用データ"}, {"id": "p111", "cat": "メイカー一般", "q": ["CADとは何ですか", "3D CADの役割を教えて"], "a": "CADはコンピュータで設計図を描くためのソフトや技術です。3D CADでは立体を画面上で作って確認でき、そのデータから3Dプリントや加工ができます。", "src": "デモ用データ"}, {"id": "p112", "cat": "メイカー一般", "q": ["SVG形式とは何ですか", "ベクター画像の形式を教えて"], "a": "SVGは、拡大しても粗くならないベクター形式の画像ファイルです。レーザーカッターの切断データなど、線の正確さが求められる用途でよく使われます。", "src": "デモ用データ"}, {"id": "p113", "cat": "メイカー一般", "q": ["プロトタイピングとは何ですか", "試作を作る意味は何ですか"], "a": "プロトタイピングは、本番の前に試作品を作って確かめることです。形や使い勝手を早い段階で確かめることで、失敗を小さくし、改良のヒントを得られます。", "src": "デモ用データ"}, {"id": "p114", "cat": "メイカー一般", "q": ["ワークショップとは何ですか", "工作のワークショップでは何をしますか"], "a": "ワークショップは、参加者が実際に手を動かして体験しながら学ぶ形式の催しです。工作のワークショップでは、講師の説明を聞きながら作品を1つ作り上げます。", "src": "デモ用データ"}, {"id": "p115", "cat": "安全・素材", "q": ["工作で保護メガネが必要な理由は", "作業の安全の基本を教えて"], "a": "保護メガネは、切った破片や粉、飛んだ材料から目を守ります。切断や削る作業、はんだ付けの際には着けるのが基本です。けがを防ぐ一番の近道は、作業前の準備と確認です。", "src": "デモ用データ"}, {"id": "p116", "cat": "安全・素材", "q": ["工作で換気が大切な理由は", "塗装や接着で換気が必要なのはなぜですか"], "a": "塗料や接着剤、はんだの煙には体に良くない成分が含まれることがあります。窓を開ける、換気扇を使うなど、空気の入れ替えをしながら作業します。", "src": "デモ用データ"}, {"id": "p117", "cat": "安全・素材", "q": ["やけどを防ぐにはどうしますか", "はんだごてやホットプレートの注意は"], "a": "熱い道具は、熱い部分が見えにくいことがあります。使い終わってもしばらくは熱いので、置き場所を決めて触らない、周りの人に声をかける、冷めたことを確認してから片付ける、が基本です。", "src": "デモ用データ"}, {"id": "p118", "cat": "安全・素材", "q": ["粉じんへの対策を教えて", "木を削るときの注意は"], "a": "木や樹脂を削ると細かい粉じんが出ます。マスクを着け、集じんや掃除をこまめに行います。粉が舞う作業は、目や呼吸を守る準備をしてから行います。", "src": "デモ用データ"}, {"id": "p119", "cat": "安全・素材", "q": ["工具の保管の基本を教えて", "道具を安全にしまう方法は"], "a": "工具は、刃物にはカバーを付ける、定位置にしまう、子どもの手の届かない場所に置く、が基本です。使い終わったらすぐ片付ける習慣が事故を防ぎます。", "src": "デモ用データ"}, {"id": "p120", "cat": "安全・素材", "q": ["子どもと工作するときの注意を教えて", "親子工作の安全ポイントは"], "a": "子どもと工作するときは、年齢に合った道具を選ぶこと、刃物や熱い道具は大人が担当すること、作業の前に約束事を決めることが大切です。無理のない作品から始めると安全に楽しめます。", "src": "デモ用データ"}, {"id": "p121", "cat": "安全・素材", "q": ["乾電池の捨て方を教えて", "電池の廃棄方法は"], "a": "使い終わった乾電池は、自治体のルールに従って回収に出します。端子にテープを貼って絶縁すると安全です。充電式電池は販売店の回収ボックスに出せることが多いです。", "src": "デモ用データ"}, {"id": "p122", "cat": "安全・素材", "q": ["リチウム電池の取り扱いの注意を教えて", "リポバッテリーは危険ですか"], "a": "リチウム系の電池は、強い衝撃や傷、誤った充電で発熱・発火することがあります。膨らんだり傷ついた電池は使わず、専用の充電器と保管方法を守ります。", "src": "デモ用データ"}, {"id": "p123", "cat": "コマのワークショップ", "q": ["このコマの組み立て方を教えて", "コマはどうやって組み立てますか", "ワークショップのコマの作り方を教えて"], "a": "組み立ては3ステップです。①好きな色の本体・軸・小ディスクを選ぶ ②白い軸を本体の中心に通す（長い方が上） ③裏返して、下面に小ディスクをはめて固定する（白い半球の先端が中心に出ればOK）。あとはシールやペンでデコレーションして、上の軸をつまんで回せます。所要時間は約3分です。", "src": "デモ用データ"}, {"id": "p124", "cat": "コマのワークショップ", "q": ["このコマは何パーツでできていますか", "コマのセット内容を教えて", "パーツは何が入っていますか"], "a": "3パーツで1セットです。本体ディスク（直径44mm・厚さ5mm）、軸（直径8mm・長さ27mm、1本で上下兼用）、ロック用の小ディスク（直径21mm・厚さ4mm）。ワッシャーやキャップは使いません。", "src": "デモ用データ"}, {"id": "p125", "cat": "コマのワークショップ", "q": ["軸の向きはどっちが上ですか", "軸の上下が分かりません", "白い軸はどちら向きに入れますか"], "a": "白い軸は、長い円柱の方が上です。上の長い部分は指でつまんで回すハンドル、下に短く出る半球の先端が地面に接する接地点になります。軸は本体を貫通して上下に出る一体型です。", "src": "デモ用データ"}, {"id": "p126", "cat": "コマのワークショップ", "q": ["小さいディスクは何のためですか", "赤い小ディスクの役割を教えて", "ロック用ディスクとは何ですか"], "a": "小ディスクは本体の下面に重ねてはめるパーツで、軸の抜け止め（ロック）の役割があります。色のアクセントにもなります。中心からは軸の白い半球の先端が出ます。", "src": "デモ用データ"}, {"id": "p127", "cat": "コマのワークショップ", "q": ["軸が固くて入りません", "パーツがはめにくい時はどうしますか", "はめ合いが固いです"], "a": "はめ合いは「子どもの力で入って、回しても抜けない」固さに設計されています（軸8mmに対して穴は約0.3mm大きめ）。固くて入らない場合は無理に押し込まず、ブースのスタッフに声をかけてください。パーツの取り外しやバリ取りはスタッフが行います。", "src": "デモ用データ"}, {"id": "p128", "cat": "コマのワークショップ", "q": ["軸が緩くて抜けてしまいます", "はめ合いが緩い時はどうしますか", "回すと軸が抜けます"], "a": "緩い個体は、スタッフがテープや接着剤で調整できます。回している途中で抜けてしまう場合は、そのまま使わずブースのスタッフに見せてください。", "src": "デモ用データ"}, {"id": "p129", "cat": "コマのワークショップ", "q": ["軸が折れてしまいました", "パーツが壊れた時の対処法は", "コマが破損しました", "軸が折れちゃった時はどうしますか", "壊れたパーツは交換できますか"], "a": "壊れた軸は安全のためそのまま使わず、ブースのスタッフに見せてください。破損した軸はスタッフが確認して交換します。ブースには予備パーツも用意しています。", "src": "デモ用データ"}, {"id": "p130", "cat": "コマのワークショップ", "q": ["本体が欠けてしまいました", "パーツが割れた時の対処法は", "ヒビが入ってしまいました"], "a": "欠けたり割れたりしたパーツは危ないので使わずに、ブースのスタッフに見せてください。ブースには予備パーツを用意しています。交換や買い直しができるかどうかは、スタッフがその場で案内します。", "src": "デモ用データ"}, {"id": "p131", "cat": "コマのワークショップ", "q": ["パーツを1つなくしてしまいました", "軸だけ買えますか", "小ディスクだけ購入できますか"], "a": "このコマはパーツごとに値段がついているので、足りないパーツだけを買い足すこともできます（軸100円、小ディスク標準色100円／特殊色150円、本体標準色200円／特殊色250円）。詳しくはブースのスタッフに聞いてください。", "src": "デモ用データ"}, {"id": "p132", "cat": "コマのワークショップ", "q": ["このコマはいくらですか", "ワークショップの値段を教えて", "参加費はいくらですか"], "a": "選んだパーツの合計が値段になります。本体：標準色200円／特殊色（ラメ・クリア・蓄光）250円、軸：100円、小ディスク：標準色100円／特殊色150円。合計は400〜500円です（標準の組み合わせで400円）。", "src": "デモ用データ"}, {"id": "p133", "cat": "コマのワークショップ", "q": ["何歳から遊べますか", "小さい子どもでも大丈夫ですか", "対象年齢を教えて"], "a": "対象は4歳から大人までです。先端は丸く設計していますが、小さいパーツがあるため、3歳以下のお子さんは保護者の方と一緒に遊んでください。", "src": "デモ用データ"}, {"id": "p134", "cat": "コマのワークショップ", "q": ["このコマの回し方を教えて", "うまく回すコツはありますか", "どうやって回しますか"], "a": "本体の上に出ている軸を指でつまみ、まっすぐ立てたまま勢いよくひねって回します。ワークショップでは対戦台で試し回しができます。まっすぐ安定して回し始めるのが、長く回すコツです。", "src": "デモ用データ"}, {"id": "p135", "cat": "コマのワークショップ", "q": ["コマに絵を描けますか", "デコレーションはできますか", "シールは貼れますか"], "a": "はい。ワークショップでは丸シールや油性カラーペンで自由にデコレーションできます。組み立てた後にデコレーションして、自分だけのコマに仕上げます。", "src": "デモ用データ"}, {"id": "p136", "cat": "コマのワークショップ", "q": ["パーツの組み替えはできますか", "違う形のコマはありますか", "本体の種類は選べますか"], "a": "本体にはいろいろな形の種類があり、色も選べます。軸は全タイプ共通規格（直径8mm）なので、本体・軸・小ディスクを自由に組み替えて遊べます。角は丸くしてあるので、対戦で当たっても危なくない設計です。", "src": "デモ用データ"}, {"id": "p137", "cat": "コマのワークショップ", "q": ["このコマは何でできていますか", "コマの材料を教えて", "どうやって作っているのですか"], "a": "このコマは3Dプリンターで印刷したPLA樹脂製です。パーツはすべて平らに置いて印刷できる形に設計されていて、サポート材なしで作れます。", "src": "デモ用データ"}, {"id": "p138", "cat": "コマのワークショップ", "q": ["逆さゴマはありますか", "ひっくり返るコマは買えますか", "逆立ちゴマの実演はありますか"], "a": "ひっくり返りゴマ（逆立ちゴマ）は、ブースで実演用の目玉として用意しています。回転の勢いや形の条件が合うと上下がひっくり返って回り続けますが、条件がシビアで毎回必ず返るわけではありません。販売用の量産は今後の候補で、今回は実演でお楽しみください。", "src": "デモ用データ"}, {"id": "p139", "cat": "コマのワークショップ", "q": ["作ったコマは持ち帰れますか", "袋はもらえますか"], "a": "はい、作ったコマは袋に入れて持ち帰れます。", "src": "デモ用データ"}, {"id": "p140", "cat": "コマのワークショップ", "q": ["子どもが使っても安全ですか", "安全性は考えられていますか", "安全に遊べるように作られていますか"], "a": "はい、安全に遊べることを考えて設計しています。先端は丸くしてあり、種類を増やすときも「角は丸める」「薄い刃は作らない」という決まりにしています。はめ合いは、子どもの力で組み立てられて、回しても抜けにくい固さに調整しています。対象は4歳からで、3歳以下のお子さんは保護者の方と一緒に遊んでください。", "src": "デモ用データ"}, {"id": "p141", "cat": "コマのワークショップ", "q": ["角の形はどうなっていますか", "角は丸くなっていますか", "先端の形はどうなっていますか", "先端は丸いですか"], "a": "先端は丸く設計してあります。軸の先端は半球の形です。ブレード型のような形の種類でも角は丸める（目安としてR2以上）ことにしていて、薄さ3mm未満の刃は作りません。", "src": "デモ用データ"}, {"id": "p142", "cat": "コマのワークショップ", "q": ["小さい子が口に入れたらどうなりますか", "誤飲について教えてください", "誤飲の対策はしていますか", "小さいパーツの誤飲が心配です", "誤飲が心配です"], "a": "一番小さいパーツは、ロック用の小ディスク（直径21mm・厚さ4mm）です。小さいパーツがあるため対象年齢は4歳からにしていて、3歳以下のお子さんは保護者の方と一緒に遊ぶよう案内しています。小さなお子さんが口に入れないよう、そばで見守ってあげてください。", "src": "デモ用データ"}, {"id": "p143", "cat": "コマのワークショップ", "q": ["割れた破片は危ないですか", "破片でケガをする心配はありますか", "壊れたコマは危ないですか", "割れた時はどうしますか"], "a": "割れたり欠けたりしたパーツは、そのまま遊ばずにブースのスタッフに渡してください。破損した軸は、スタッフが確認して交換します。パーツの取り外しやバリ取りは、ケガを防ぐためスタッフだけが行います。", "src": "デモ用データ"}, {"id": "p144", "cat": "コマのワークショップ", "q": ["なぜ4歳からなんですか", "対象年齢はどう決めたんですか", "小さい子はなぜ保護者同伴なんですか"], "a": "小さいパーツ（ロック用小ディスクは直径21mm）があることと、組み立てに指先の力が少し要るため、対象は4歳からにしています。3歳以下のお子さんは、保護者の方と一緒であれば参加できます。", "src": "デモ用データ"}, {"id": "p145", "cat": "出展者について", "q": ["このコマを作ったのは誰ですか", "出展者はどんな人ですか", "作った人について教えてください"], "a": "出展者の高橋蒼介です。大垣Mini Maker Faire 2026に「個人・コミュニティ」の区分で個人出展しています。ものづくりが好きで、このコマも、質問に答えている特化型AI「Athena（アテナ）」も自分で開発しました。ブースではコマの実演と販売をしています。", "src": "デモ用データ"}, {"id": "p146", "cat": "出展者について", "q": ["Athenaを作ったのは誰ですか", "このAIは誰が開発したんですか", "Athenaの開発者は誰ですか"], "a": "Athenaは、出展者の高橋蒼介が開発している特化型AIです。決まった範囲の情報の中から、出典を示して答えるのが特徴です。このデモは、その公開版として用意しました。", "src": "デモ用データ"}, {"id": "p147", "cat": "出展者について", "q": ["出展者は何歳ですか", "出展者は学生ですか", "出展者についてもっと詳しく知りたいです"], "a": "詳しいことは、ブースにいる本人に直接聞いてみてください。ブースでは、コマの実演と販売をしています。", "src": "デモ用データ"}, {"id": "p148", "cat": "もっと知りたい方へ", "q": ["Athenaの作り方を公開していますか", "作り方の記事はありますか", "技術的な記事はありますか"], "a": "はい、noteで公開しています。アカウントは「しそ」（shisoatx）です。Athenaの作り方を小分けにした技術シリーズや、レーザーカッターなど工作機器の使い方の記事を出しています。 https://note.com/shisoatx", "src": "デモ用データ"}, {"id": "p149", "cat": "もっと知りたい方へ", "q": ["もっと詳しく知りたいです", "ブログや記事はやっていますか", "noteはやっていますか"], "a": "もっと詳しく知りたい方には、noteの記事がおすすめです。「しそ」（shisoatx）のアカウントで、Athenaの開発を分けて書いた技術シリーズと、工作機器の使い方の記事を公開しています。 https://note.com/shisoatx", "src": "デモ用データ"}, {"id": "p150", "cat": "もっと知りたい方へ", "q": ["Instagramはやっていますか", "インスタはありますか", "紹介動画はありますか"], "a": "はい、Instagramで紹介しています。アカウントは @takasooo._.official で、Athenaの紹介動画や写真を投稿しています。 https://www.instagram.com/takasooo._.official/", "src": "デモ用データ"}, {"id": "p151", "cat": "もっと知りたい方へ", "q": ["Athenaの写真や動画はどこで見られますか", "SNSはやっていますか", "動画で見たいです"], "a": "Instagramの @takasooo._.official で、Athenaの紹介動画や写真を公開しています。 https://www.instagram.com/takasooo._.official/", "src": "デモ用データ"}, {"id": "p152", "cat": "Athenaについて", "q": ["Athenaの特長を教えて", "Athenaについて教えて", "Athenaは何が得意ですか"], "a": "Athenaは、開発者が自分で作っている特化型AIです。汎用AIとは違い、社内FAQやマニュアルなど決まった範囲の情報から、出典を示して答えます。データは外部に送信せず、作り話はしません。使われるほど学習して賢くなります。独自規格「Aegis」による能動的サイバー防御も備えています。現在は開発者自身の活動内のみで使用中です。一般公開・企業向け提供はこれから行います。", "src": "デモ用データ"}, {"id": "p153", "cat": "Athenaについて", "q": ["Athenaはどこで使えますか", "Athenaを会社で使えますか", "Athenaは一般公開されていますか"], "a": "現在Athenaは、開発者自身の活動の中だけで使っています。一般公開と、会社などへの企業向け提供は、これから行う予定です。開発の様子はnoteの記事で発信しています。 https://note.com/shisoatx", "src": "デモ用データ"}];
